import numpy as np
def _lattice(n_per_class):
    ncol = n_per_class
    n = 2 * ncol
    is_v = np.zeros(n, float)
    adj = np.zeros((n, n), float)
    for r in range(2):
        for c in range(ncol):
            i = r * ncol + c
            is_v[i] = 1.0 if (r + c) % 2 == 0 else 0.0
            for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < 2 and 0 <= cc < ncol:
                    adj[i, rr * ncol + cc] = 1.0
    return is_v, adj
is_v, adj = _lattice(4)
